(function(){
  const EMOJI_DATA = {"↔":"","↩":"","⏩":"","⏸":"","▶":"","☀":"","☁":"","☂":"","☔":"","⚓":"","⚙":"","⚠":"","⚡":"","⚾":"","⛄":"","⛪":"","⛵":"","✅":"","✖":"","✨":"","❄":"","❌":"","❓":"","❔":"","➗":"","➡":"","⬅":"","⭐":"","🃏":"","🌀":"","🌃":"","🌈":"","🌉":"","🌊":"","🌋":"","🌌":"","🌍":"","🌏":"","🌑":"","🌙":"","🌛":"","🌝":"","🌞":"","🌟":"","🌠":"","🌰":"","🌱":"","🌲":"","🌳":"","🌴":"","🌹":"","🌺":"","🌻":"","🌾":"","🌿":"","🍀":"","🍁":"","🍃":"","🍄":"","🍇":"","🍊":"","🍎":"","🍐":"","🍑":"","🍒":"","🍓":"","🍚":"","🍜":"","🍞":"","🍩":"","🍮":"","🍰":"","🍳":"","🍵":"","🎀":"","🎁":"","🎃":"","🎄":"","🎅":"","🎉":"","🎍":"","🎎":"","🎡":"","🎢":"","🎧":"","🎨":"","🎩":"","🎪":"","🎫":"","🎭":"","🎮":"","🎯":"","🎰":"","🎲":"","🏃":"","🏆":"","🏠":"","🏡":"","🏪":"","🏭":"","🏮":"","🏯":"","🏰":"","🏺":"","🐀":"","🐁":"","🐅":"","🐆":"","🐇":"","🐈":"","🐉":"","🐊":"","🐋":"","🐍":"","🐒":"","🐓":"","🐕":"","🐖":"","🐗":"","🐙":"","🐚":"","🐛":"","🐝":"","🐟":"","🐠":"","🐡":"","🐢":"","🐣":"","🐥":"","🐦":"","🐧":"","🐨":"","🐩":"","🐪":"","🐬":"","🐭":"","🐮":"","🐯":"","🐰":"","🐱":"","🐲":"","🐳":"","🐵":"","🐶":"","🐸":"","🐺":"","🐻":"","🐼":"","🐾":"","👊":"","👑":"","👗":"","👘":"","👠":"","👤":"","👯":"","👸":"","👹":"","👺":"","👻":"","👼":"","👽":"","👾":"","👿":"","💀":"","💊":"","💍":"","💎":"","💐":"","💠":"","💡":"","💥":"","💦":"","💧":"","💨":"","💪":"","💮":"","💰":"","💾":"","📁":"","📄":"","📅":"","📊":"","📋":"","📍":"","📎":"","📏":"","📐":"","📓":"","📖":"","📘":"","📚":"","📜":"","📝":"","📤":"","📥":"","📦":"","📮":"","🔁":"","🔄":"","🔆":"","🔋":"","🔎":"","🔑":"","🔒":"","🔗":"","🔢":"","🔥":"","🔦":"","🔩":"","🔬":"","🔭":"","🔮":"","🔹":"","🕌":"","🕺":"","🗻":"","🗼":"","🗾":"","🗿":"","😀":"","😈":"","😎":"","😪":"","😫":"","😼":"","🙂":"","🙏":"","🚀":"","🚂":"","🚄":"","🚋":"","🚗":"","🚪":"","🚫":"","🛖":"","🛟":"","🛸":"","🟤":"","🤖":"","🤝":"","🤡":"","🤩":"","🤴":"","🥁":"","🥊":"","🥐":"","🥚":"","🥜":"","🥦":"","🥩":"","🥯":"","🥷":"","🥾":"","🦀":"","🦁":"","🦂":"","🦄":"","🦅":"","🦇":"","🦈":"","🦉":"","🦋":"","🦌":"","🦍":"","🦎":"","🦏":"","🦓":"","🦕":"","🦖":"","🦞":"","🦣":"","🦨":"","🦫":"","🦬":"","🦾":"","🦿":"","🧊":"","🧋":"","🧚":"","🧜":"","🧟":"","🧠":"","🧨":"","🧩":"","🧪":"","🧫":"","🧬":"","🧭":"","🧮":"","🧯":"","🧰":"","🧱":"","🧲":"","🧵":"","🧷":"","🧸":"","🧹":"","🧽":"","🧾":"","🧿":"","🪃":"","🪄":"","🪆":"","🪐":"","🪓":"","🪔":"","🪙":"","🪚":"","🪜":"","🪝":"","🪞":"","🪟":"","🪠":"","🪡":"","🪣":"","🪤":"","🪧":"","🪨":"","🪩":"","🪪":"","🪫":"","🪬":"","🪲":"","🪵":"","🪶":"","🪷":"","🪸":"","🪼":"","🪿":"","🫎":"","🫖":"","🫗":"","🫘":"","🫙":"","🫠":"","🫧":"","⏱":"","☠":"","♨":"","♾":"","⚔":"","⚗":"","⚱":"","⛈":"","⛓":"","⛩":"","⛰":"","❤":"","⬆":"","⬇":"","🌥":"","🌦":"","🌧":"","🌩":"","🌪":"","🌫":"","🌬":"","🎖":"","🎟":"","🏋":"","🏔":"","🏗":"","🏘":"","🏙":"","🏛":"","🏜":"","🏝":"","🏞":"","🏳":"","🕯":"","🖋":"","🗝":"","🗡":"","🗺":"","🛠":"","🛡":"","🛰":"","🛳":"","👨‍🌾":"","👨‍🍳":"","👨‍🏫":"","🧛‍♀":""};
  const EXTRA_EMOJI_DATA = {"🍛":"","🏊":"","🍅":"","🎵":"","⚽":"","🏀":"","⛺":"","🎣":"","🩰":"","🏕":"","💃":""};
  const DATA_PREFIX = "data:image/png;base64,";
  function norm(s){ return String(s||"").replace(/\uFE0F|\uFE0E/g,""); }
  function getSrc(emo){
    if(!emo) return null;
    if(EMOJI_DATA[emo]) return DATA_PREFIX + EMOJI_DATA[emo];
    if(EXTRA_EMOJI_DATA[emo]) return DATA_PREFIX + EXTRA_EMOJI_DATA[emo];
    const n = norm(emo);
    if(EMOJI_DATA[n]) return DATA_PREFIX + EMOJI_DATA[n];
    if(EXTRA_EMOJI_DATA[n]) return DATA_PREFIX + EXTRA_EMOJI_DATA[n];
    return null;
  }
  const EMOJI_RE = (function(){
    try {
      // ZWJ sequences + flags + pictographs (modern browsers)
      return new RegExp("(?:\\p{Regional_Indicator}{2}|\\p{Extended_Pictographic}(?:\\uFE0F|\\uFE0E)?(?:\\u200D\\p{Extended_Pictographic}(?:\\uFE0F|\\uFE0E)?)*)(?:\\uFE0F|\\uFE0E)?","gu");
    } catch(e) {
      // Fallback: broad range (won't catch ZWJ perfectly, but won't crash)
      return /[\u{1F000}-\u{1FAFF}]/gu;
    }
  })();
  function shouldSkip(node){
    const p = node && node.parentNode;
    if(!p || p.nodeType !== 1) return false;
    const tag = p.tagName;
    if(tag === "SCRIPT" || tag === "STYLE" || tag === "TEXTAREA" || tag === "INPUT") return true;
    if(p.closest && p.closest("img,svg,canvas")) return true;
    if(p.closest && p.closest("[data-emoji-skip]")) return true;
    return false;
  }
  function parse(root){
    root = root || document.body;
    if(!root) return;
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode(node){
        if(!node.nodeValue) return NodeFilter.FILTER_REJECT;
        if(shouldSkip(node)) return NodeFilter.FILTER_REJECT;
        if(!EMOJI_RE.test(node.nodeValue)) return NodeFilter.FILTER_REJECT;
        EMOJI_RE.lastIndex = 0;
        return NodeFilter.FILTER_ACCEPT;
      }
    });
    const nodes = [];
    while(walker.nextNode()) nodes.push(walker.currentNode);
    for(const node of nodes){
      const s = node.nodeValue;
      EMOJI_RE.lastIndex = 0;
      let m, last = 0;
      let changed = false;
      const frag = document.createDocumentFragment();
      while((m = EMOJI_RE.exec(s)) !== null){
        const emo = m[0];
        const src = getSrc(emo);
        if(src){
          if(m.index > last) frag.appendChild(document.createTextNode(s.slice(last, m.index)));
          const img = document.createElement("img");
          img.className = "emoji";
          img.alt = emo;
          img.draggable = false;
          img.decoding = "async";
          img.src = src;
          // mimic common twemoji sizing behavior
          img.style.height = "1em";
          img.style.width = "1em";
          img.style.verticalAlign = "-0.1em";
          frag.appendChild(img);
          last = m.index + emo.length;
          changed = true;
        }
      }
      if(!changed) continue;
      if(last < s.length) frag.appendChild(document.createTextNode(s.slice(last)));
      node.parentNode.replaceChild(frag, node);
    }
  }
  window.twemoji = window.twemoji || {};
  // twemoji.parse を無効化 → OS標準の絵文字をそのまま表示する
  window.twemoji.parse = function(){};
  window.twemoji.getSrc = getSrc;
})();
